import json
for line in open('recordings/hormuz.jsonl'):
    d=json.loads(line)
    # find proposition-shaped objects
    def walk(o):
        if isinstance(o,dict):
            if 'payoff' in o and o.get('payoff'):
                print(o.get('id'), '|', o.get('kind'), '|', (o.get('claim') or '')[:110])
                r=o.get('resolution') or {}
